<script setup lang="ts">
import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import {api,errorText} from '../api';import {Bell} from 'lucide-vue-next';const notices=ref<any[]>([]),show=ref(false),error=ref('');const router=useRouter();async function load(){try{notices.value=(await api.get('/notifications')).data;}catch(e){error.value=errorText(e);}}async function toggle(){show.value=!show.value;if(show.value)await load();}async function open(n:any){try{await api.post(`/notifications/${n.id}/read`);show.value=false;router.push(n.data.path);await load();}catch(e){error.value=errorText(e);}}onMounted(load);
</script>
<template><div class="notification-wrap"><button class="notification-button" @click="toggle" :aria-expanded="show" aria-label="Ver notificaciones"><Bell :size="18"/><span v-if="notices.some(n=>!n.read_at)" class="notification-dot"></span></button><div v-if="show" class="notification-menu"><h3>Notificaciones</h3><p v-if="error" class="error">{{error}}</p><button v-for="n in notices" :key="n.id" class="notification-item" :class="{unread:!n.read_at}" @click="open(n)">{{n.data.title}}<small>{{n.read_at?'Leída':'Nueva'}}</small></button><p class="empty compact" v-if="!notices.length">No tienes notificaciones.</p><button class="button" @click="show=false">Cerrar</button></div></div></template>
